/*
====================================================================================================
Division		|	Lidl
Solution		|	Operational Logistics (LOGOP)
DB schema		|	data
DB table		|	t_quintiq_reportedtour_1
Description		|	QUINTIQ table for raw data
====================================================================================================
*/

CREATE TABLE DATA.t_quintiq_reportedtour_1 (
client_id 		NUMBER(38,0) 	NOT NULL COMMENT 'Client id - calculated based on the country_1 code',
lidl_country 	VARCHAR(3) 		NOT NULL COMMENT 'Country_1 code. Original field name bic_zmlila',
source_system 	VARCHAR(30) 	NOT NULL COMMENT 'Source system',
wh_id 			VARCHAR(5) 		NOT NULL COMMENT 'Warehouse ID',
address_id_seq 					VARCHAR(5000) 	NULL 		COMMENT 'Contains the IDs of all the non rdc addresses this tour_1 visits in the order the are visited',
address_name_seq 				VARCHAR(5000) 	NULL 		COMMENT 'Contains the long names of all the non rdc addresses this tour_1 visits in the order the are visited (excluding country_1 code)',
calendar_week 					NUMBER(38,0) 	NULL 		COMMENT 'Calenderweek of GlobalParameters.DeliveryDateEnd',
delivery_dt 					DATE 			NULL 		COMMENT 'End of the delivery day to optimize for (max 24hrs after start).',
calc_dist 						NUMBER(38,10)	NULL 		COMMENT 'Distance traveled during the tour_1 as calculated by the program',
calc_dur 						VARCHAR(512) 	NULL 		COMMENT 'Duration of the tour_1',
earliest_start_tmsp 			TIMESTAMP 		NULL 		COMMENT 'Earliest Start Time for the tour_1',
tour_gid 						VARCHAR(5000)	NOT NULL 	COMMENT 'GID is to have a unique identifier of a tour_1 across different delivery days for the same RDC.',
store_dlv_fg 					BOOLEAN 		NULL 		COMMENT 'At least one shipment delivery to a store is planned',
haulier 						VARCHAR(512) 	NULL 		COMMENT 'Stores the value of the Haulier of the lowest resources (ID) within this tour_1 with IsMotorVehicle = TRUE Attribute HaulierName on Tour_1',
tour_id 						VARCHAR(5000) 	NULL 		COMMENT 'Quintiq generated Tour_1 ID',
license_plate 					VARCHAR(512) 	NULL 		COMMENT 'User entered license plate number of the vehicle used for the tour. Or its based on route Attribute LicensePlateCalc on Tour_1',
license_plate_trailer 			VARCHAR(512) 	NULL 		COMMENT 'User entered license plate number of the trailer used for this the tour_1 Or its based on route Attribute LicensePlateTrailerCalc on Tour_1',
loaded_shipments 				NUMBER(38,10) 	NULL 		COMMENT 'Pallet positions at the start of the tour_1 Attribute LoadedQuantity1 on Tour_1',
product_types_list 				VARCHAR(512) 	NULL 		COMMENT 'List of all the product types shipped as part of this tour_1',
resource_tech 					VARCHAR(512) 	NULL 		COMMENT 'Resource.ResourceTechnique.ID (if multiple Resources are used for the tour_1, show all resoruce techniques comma separated)',
resource_type 					VARCHAR(512) 	NULL 		COMMENT 'Resource.ResourceType.ID (if multiple Resources are used for the tour_1, show all resoruce types comma separated)',
tour_status 					VARCHAR(512) 	NULL 		COMMENT 'The status_1 of this tour_1',
max_cap_sum 					NUMBER(38,10) 	NULL 		COMMENT 'The sum of all max capacity 1 in the resources within this tour_1',
tollcostcalculated 				NUMBER(38,10) 	NULL 		COMMENT 'Toll cost',
calc_toll_dist2 				NUMBER(38,10) 	NULL 		COMMENT 'Toll distance of type 2 traveled during the tour_1 as calculated by the program',
calc_toll_dist 					NUMBER(38,10) 	NULL 		COMMENT 'Toll distance traveled during the tour_1 as calculated by the program',
user_dist 						NUMBER(38,10) 	NULL 		COMMENT 'User entered distance for the tour_1',
user_dur 						VARCHAR(512) 	NULL 		COMMENT 'User entered duration for the tour_1',
user_shift 						NUMBER(38,0) 	NULL 		COMMENT 'The shift to which the tour_1 belongs. In case the driver swap is after the pickup actions and therefore the tour_1 belongs to two shifts this attribute needs to contain the later shift.',
user_toll_dist2 				NUMBER(38,10) 	NULL 		COMMENT 'User entered toll distance of type 2 for the tour_1',
user_toll_dist 					NUMBER(38,10) 	NULL 		COMMENT 'User entered toll distance for the tour_1',
util_pallet_pos 				NUMBER(38,10) 	NULL 		COMMENT 'Utilization of the pallet positions when leaving the RDC',
util_pallet_pos_elke 			NUMBER(38,10) 	NULL 		COMMENT 'The utilization of the resources that are going to stores',
util_no_return_elke 			NUMBER(38,10) 	NULL 		COMMENT 'The overall utilization of pallet positions in a resource over distance driven per tour_1 that has store deliveries excluding the returns.',
resourcesetid 						VARCHAR(512) 	NULL 		COMMENT 'The ID of the resource set',
indicatorquality 					VARCHAR(512) 	NULL 		COMMENT 'Name of the quality indicator',
usertolldistance3 					NUMBER(38,10) 	NULL 		COMMENT '[Overrule] User entered toll distance for the tour_1',
usertrailer1consumption 			NUMBER(38,10) 	NULL 		COMMENT 'Fuel/Energy consumption of trailer 1 as set by the user',
tourend 							TIMESTAMP 		NULL 		COMMENT 'End of a tour. Original name: End',
totalnum1apalletsplannedconverted 	NUMBER(38,10) 	NULL 		COMMENT 'The total quantity1 converted of 1a pallets planned on this tour_1 which are picked up at the RDC and delivered at a store',
usertrailer2consumption 			NUMBER(38,10) 	NULL 		COMMENT 'Fuel/Energy consumption of trailer 2 as set by the user',
totalnum1bpalletsplanned 			NUMBER(38,10) 	NULL 		COMMENT 'The total quantity1 of 1b pallets (returns and transfers) planned on this tour_1 which are not delivered at a store',
tolldistance3calculated 			NUMBER(38,10) 	NULL 		COMMENT 'Toll distance of type 3 travelled during the tour_1 as calculated by the program',
summaxcapacity1converted 			NUMBER(38,10) 	NULL 		COMMENT 'The sum of all max capacity 1 converted in the resources within this tour_1',
drivingdrivetypeid 					VARCHAR(512) 	NULL 		COMMENT 'ID of driving drive type',
trailer2drivetypeid 				VARCHAR(512) 	NULL 		COMMENT 'ID of trailer 2 drive type',
indicatortimeuser 					VARCHAR(512) 	NULL 		COMMENT 'Time indicator set by the user',
indicatorshiftid 					VARCHAR(512) 	NULL 		COMMENT 'The unique identifier of shift indicator',
toursequenceid 						NUMBER(38,0) 	NULL 		COMMENT 'The SeqNr of the tour_1',
haulierid 							VARCHAR(512) 	NULL 		COMMENT 'The ID of the haulier',
userdrivingconsumption 				NUMBER(38,10) 	NULL 		COMMENT 'Fuel/Energy consumption of the motor vehicle as set by the user',
totalnum1bpalletsplannedconverted 	NUMBER(38,10) 	NULL 		COMMENT 'The total quantity1 converted of 1b pallets (returns and transfers) planned on this tour_1 which are not delivered at a store',
totalnum1apalletsplanned 			NUMBER(38,10) 	NULL 		COMMENT 'The total quantity1 of 1a pallets planned on this tour_1 which are picked up at the RDC and delivered at a store',
indicatorqualitycomment 			VARCHAR(512) 	NULL 		COMMENT 'A comment of the selected quality indicator',
indicatorcost 						VARCHAR(512) 	NULL 		COMMENT 'Name of the cost indicator',
trailer1drivetypeid 				VARCHAR(512) 	NULL 		COMMENT 'ID of trailer 1 drive type',
licenseplatetrailer2 				VARCHAR(512) 	NULL 		COMMENT 'User entered license plate number of the trailer used for this the tour_1 Or its based on route. Attribute LicensePlateTrailerCalc on Tour_1',
tourstart 							TIMESTAMP 		NULL 		COMMENT 'Start of a tour. Original name: Start',
indicatoraddress 					VARCHAR(512) 	NULL 		COMMENT 'Concatenation of all unique addresses indicators planned on this Tour_1',
tiko 								BOOLEAN 		NULL 		COMMENT 'True if there is at least one compartment in this tour_1 that is frozen',
isoneway 							BOOLEAN 		NULL 		COMMENT 'True if the tour_1 is used for one way, dismount resources at the end address_1(not RDC)',
totalnumpalletswithisdeliverytoexternalwarehouse	NUMBER(38,10) 	NULL 		COMMENT 'The total number of pallets for all shipment legs on this tour_1 which were delivered to an external warehouse',
totalnumpalletswithisdeliverytointernalwarehouse    NUMBER(38,10) 	NULL 		COMMENT 'The total number of pallets for all shipment legs on this tour_1 which were delivered to an internal warehouse',
totalnumpalletswithisdeliverytononfoodwarehouse     NUMBER(38,10) 	NULL 		COMMENT 'The total number of pallets for all shipment legs on this tour_1 which were delivered to a non food warehouse',
indicatorcostamount                                 NUMBER(38,10) 	NULL 		COMMENT 'The amount of the cost indicator',
hasnonfoodwarehouse                                 BOOLEAN 		NULL 		COMMENT 'TRUE if at least one of the addresses visited in the tour_1 is a non food warehouse',
hasinternalwarehouse                                BOOLEAN 		NULL 		COMMENT 'TRUE if at least one of the addresses visited in the tour_1 is an internal warehouse',
hasexternalwarehouse                                BOOLEAN 		NULL 		COMMENT 'TRUE if at least one of the addresses visited in the tour_1 is an external warehouse',
meansoftransportid                                  VARCHAR(512) 	NULL 		COMMENT 'A concatenation of the means of transport ID of the driving resource, trailer1 and trailer2',
meansoftransportname                                VARCHAR(512) 	NULL 		COMMENT 'A concatenation of the means of transport name of the driving resource, trailer1 and trailer2',
indicatorqualityids					                VARCHAR(512) 	NULL 		COMMENT 'Concatenated string of the IDs of all assigned quality indicators',
distancedrivenactual				                NUMBER(38,10) 	NULL 		COMMENT 'The actual distance driven, received by Telematics',
dwh_load_id 	NUMBER(38,0) 		NOT NULL COMMENT 'Load id',
dwh_created 	TIMESTAMP 			NOT NULL COMMENT 'Record created at',
dwh_updated 	TIMESTAMP 			NOT NULL COMMENT 'Record updated at',
dwh_valid_from 	DATE 				NOT NULL COMMENT 'Valid from date',
dwh_valid_to 	DATE 				NOT NULL COMMENT 'Valid to date',
deleted_fg 		BOOLEAN 			NOT NULL COMMENT 'Flag if record is deleted',
PRIMARY KEY (client_id,wh_id,tour_gid,dwh_valid_from)
) COMMENT = 'Object type in quintiq is ReportedTour Stores tours that are reported';